set -eu
dburl=$(sudo docker inspect gsa-tv-control-plane --format '{{range .Config.Env}}{{println .}}{{end}}' | awk -F= '$1=="DATABASE_URL"{sub(/^DATABASE_URL=/,"");print;exit}')
sudo docker run --pull=never --rm --network host postgres:15-alpine psql "$dburl" -X -qAt -v ON_ERROR_STOP=1 -c "SELECT state,count(*),count(*) FILTER(WHERE metadata->>'fact_check_status'='pass'),count(*) FILTER(WHERE metadata->>'production_package_ready'='true') FROM public.gsa_tv_ai_projects WHERE metadata->>'broadcast_date'='2026-09-10' GROUP BY state; SELECT p.name,b.planned_duration_s,b.media_item_id IS NOT NULL AS linked,b.metadata->>'production_package_path' FROM public.gsa_tv_program_blocks b JOIN public.gsa_tv_programs p ON p.id=b.program_id WHERE b.schedule_version_id=(SELECT id FROM public.gsa_tv_schedule_versions WHERE channel_id='ch-main' AND broadcast_date='2026-09-10' AND state='published' ORDER BY version DESC LIMIT 1) ORDER BY b.position; SELECT state,count(*) FROM public.gsa_tv_ai_jobs GROUP BY state;"
sudo find /opt/gsa-tv/cache/media/1/production -maxdepth 4 -name package.json -printf '%p\n' 2>/dev/null | head -n 10
